 grant select,update on all tables in schema public to service_role;
 alter table users add column role text default 'ADMIN',add column is_active integer default 1;
 alter table leads add column full_name text;
 alter table units add column layout_type_id integer;
 alter table deals add column cancelled_at timestamptz,add column terminated_by_user_id integer;
 create table tasks(id serial primary key,lead_id integer,deal_id integer,assigned_user_id integer,type text,title text,description text,due_date text,priority text,status text,idempotency_key text,updated_at timestamptz,completed_at timestamptz);
 create unique index tasks_open_type on tasks(deal_id,type) where status='OPEN' and deal_id is not null;
 create schema storage;create table storage.buckets(id text primary key,name text,public boolean,file_size_limit bigint,allowed_mime_types text[]);
 create table storage.objects(bucket_id text,name text);alter table storage.objects enable row level security;
 create table layout_types(id integer primary key,project_id integer,archived_at text,technical_plan_path text,furnished_plan_path text,image_path text);
 create table tours_360(id integer primary key,name text,project_id integer,is_active boolean,entity_type text,entity_id integer);
 create table panorama_360(id integer primary key,tour_id integer,name text,storage_path text,entity_type text,entity_id integer,initial_yaw numeric,initial_pitch numeric,initial_fov numeric,sort_order integer);
 create table panorama_hotspots(id integer primary key,panorama_id integer,hotspot_type text,label text,yaw numeric,pitch numeric,target_panorama_id integer);
 grant select,insert,update on all tables in schema public to service_role;grant usage,select on all sequences in schema public to service_role;
